import requests
from pathlib import Path
import zipfile
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    try:
        # Ensure directories exist
        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
        ZIP_DIR.mkdir(parents=True, exist_ok=True)

        # Download the file
        response = requests.get(url)
        response.raise_for_status()  # Raise an error for bad responses

        # Save the file to the download directory
        file_path = DOWNLOAD_DIR / filename
        with open(file_path, 'wb') as f:
            f.write(response.content)

        # Extract the zip file
        with zipfile.ZipFile(file_path, 'r') as zip_ref:
            zip_ref.extractall(ZIP_DIR)

        # List files in the unzipped directory
        extracted_files = [f.name for f in ZIP_DIR.iterdir() if f.is_file()]

        return ("Success", extracted_files)

    except requests.exceptions.RequestException as e:
        return (f"Error: Network-related exception occurred - {str(e)}", [])
    except zipfile.BadZipFile as e:
        return (f"Error: Bad zip file - {str(e)}", [])
    except Exception as e:
        return (f"Error: An unexpected error occurred - {str(e)}", [])

