import unicodedata
import requests
URL = 'https://api.github.com/users/'
def normalize_to_ascii(s):
    """Normalize a string to ASCII."""
    return unicodedata.normalize('NFKD', s).encode('ascii', 'ignore').decode('ascii')
def task_func(username):
    """Retrieve user information from GitHub API and normalize all string data to ASCII."""
    try:
        response = requests.get(URL + username)
        response.raise_for_status()  # Raise an HTTPError for bad responses
        user_data = response.json()

        # Normalize all string values in the dictionary to ASCII
        normalized_data = {key: normalize_to_ascii(value) if isinstance(value, str) else value for key, value in user_data.items()}

        return normalized_data

    except requests.exceptions.HTTPError as http_err:
        print(f"HTTP error occurred: {http_err}")
        raise
    except Exception as err:
        print(f"An error occurred: {err}")
        raise

